INSERT INTO `ist_berkas_kepala` (`id`, `periode_id`, `urutan`, `nama_dokumen`, `keterangan`, `link_template`, `created_at`, `updated_at`) VALUES
(3, 1, 1, 'Narasi Diri', 'Narasi refleksi keteladanan yang menggambarkan nilai, sikap, perilaku, dan kontribusi yang menjadikan Anda layak menjadi IST dalam menjalankan tugas, berinteraksi dengan rekan kerja, memberikan pelayanan, serta berkontribusi terhadap pencapaian tujuan organisasi (maksimal 500 kata)', 'https://drive.google.com/file/d/1YCLYg5Vef4hYz4pHWPsvp4yKndYh6bZo/view?usp=sharing', '2026-08-18 02:14:41', '2026-08-18 02:14:41'),
(4, 1, 2, 'Portofolio Pengembangan Diri', 'Portofolio pengembangan diri berisi 10 riwayat pengembangan diri terbaik selama 5 (lima) tahun terakhir yang dituangkan dalam format excel beserta bukti dukung', 'https://drive.google.com/file/d/1y7AWzpJRhp90EfIQCneb0UrAlxuhlqpB/view?usp=sharing', '2026-08-18 02:15:40', '2026-08-18 02:15:40'),
(5, 1, 3, 'Portofolio Inovasi', 'Portofolio inovasi/prestasi yang dituangkan dalam format excel beserta bukti dukung dan diurutkan berdasarkan inovasi/prestasi yang paling berdampak', 'https://drive.google.com/file/d/1UiHV-jcrc3o7aOWbbBuzP0Myhl50EZLK/view?usp=drive_link', '2026-08-18 02:16:17', '2026-08-18 02:16:17'),
(6, 1, 4, 'Video Promosi Diri', 'Video promosi diri yang merefleksikan keteladanan, prestasi, inovasi, dan dampak nyata, dengan menjawab pertanyaan: \"Apa kontribusi terbesar Anda sebagai pegawai BPS?\". Video menggunakan wajah asli bukan hasil rekayasa Artificial Intelligence (AI)', NULL, '2026-08-18 02:17:22', '2026-08-18 02:17:22');
